<template><div class="slide-up pb-8"><StepHeader :step="2" eyebrow="Изделие" title="Выбери основу" description="Все изделия создаются по твоему выбору." /><div class="space-y-3"><OptionCard v-for="product in PRODUCTS" :key="product.id" :title="product.name" :description="product.description" :price="product.basePrice" :selected="order.draft.product?.id === product.id" @select="order.setProduct(product)" /></div><p v-if="error" class="mt-3 text-sm text-terracotta">{{ error }}</p><BackNext back-to="/create" :disabled="!order.draft.product" @next="goNext" /></div></template>
<script setup lang="ts">import { PRODUCTS } from '~/config/catalog'; useSeoMeta({ robots: 'noindex, nofollow' }); const order = useOrderStore(); const error = ref(''); function goNext(): void { if (!order.draft.product) { error.value = 'Выберите изделие'; return } navigateTo('/design') }</script>
